// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 sendAmt, uint256 seed) public {
        sendAmt = bound(sendAmt, 0, 1 ether);

        ReceiverRec rec = new ReceiverRec();

        uint256 initialFund = 0.5 ether;
        vm.deal(address(this), initialFund + sendAmt);
        (bool okFund,) = address(c).call{value: initialFund}("");
        require(okFund);

        vm.deal(address(this), sendAmt);
        bool ok;
        try c.Command{value: sendAmt}(address(rec), "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(rec.received() == sendAmt);
    }
}

contract ReceiverRec {
    uint256 public received;
    fallback() external payable {
        received = msg.value;
    }
    receive() external payable {
        received = msg.value;
    }
}
